/**
 * lightPollution.ts
 *
 * JS/TS port of `light_pollution(lat, lon)` from calc_time.py
 * (https://github.com/astertaylor/halakhic_calc/blob/main/calc_time.py).
 *
 * The original Python looks up a single pixel from a global light-pollution
 * raster (shape 17406 x 43200 — a VIIRS-style annual composite, cropped to
 * roughly +85° to -60° latitude) without loading the whole thing into memory.
 * It does this by pre-splitting the raster into 4096x4096 tile files named
 * `lp_{tileRow}_{tileCol}.tif`, then using rasterio's windowed read to pull
 * out exactly one pixel from the correct tile.
 *
 * This port keeps that same tiling scheme (so it can reuse the same tile
 * files) and reads pixels with `geotiff.js`'s `fromUrl`, which fetches tiles
 * over HTTP using range requests so only the needed internal block of the
 * tile is downloaded.
 *
 * Tiles are expected to be served same-origin as the page (e.g. from
 * /assets/tif/), so there's no CORS/preflight concern to worry about — see
 * TILE_BASE_URL below to change the path.
 *
 * Requires: npm install geotiff
 */

import { fromUrl, GeoTIFF } from "geotiff";

// --- Constants matching the Python source -----------------------------

/** Full raster shape: [rows, cols]. */
const RASTER_SHAPE = { rows: 17406, cols: 43200 } as const;

/** Side length of each pre-split tile file, in pixels. */
const TILE_SIZE = 4096;

/** Latitude span covered by the raster (85°N down to -60°, i.e. 145°). */
const LAT_SPAN_DEG = 145;
const LAT_TOP_DEG = 85;

/** Where tile files are served from, relative to the site root. */
const TILE_BASE_URL = "/assets/tif";

// --- Internal helpers ---------------------------------------------------

/** Cache of opened GeoTIFF handles, keyed by tile filename, so repeated
 * lookups in the same tile don't reopen/refetch metadata each time. */
const tiffCache = new Map<string, Promise<GeoTIFF>>();

interface TileIndex {
  tileRow: number;
  tileCol: number;
  localRow: number;
  localCol: number;
}

/**
 * Convert lat/lon to the tile file this pixel lives in, and the pixel's
 * row/col local to that tile. Mirrors the Python function's index math
 * (including its clamping to valid raster bounds) exactly.
 */
function resolveTileIndex(lat: number, lon: number): TileIndex {
  // Python uses int(...) truncation, not floor; match it for fidelity.
  // (Values that would go negative are clamped to 0 right after anyway.)
  let latIdx = Math.trunc((-lat + LAT_TOP_DEG) * (RASTER_SHAPE.rows / LAT_SPAN_DEG));
  let lonIdx = Math.trunc((lon + 180) * (RASTER_SHAPE.cols / 360));

  latIdx = Math.max(0, Math.min(latIdx, RASTER_SHAPE.rows - 1));
  lonIdx = Math.max(0, Math.min(lonIdx, RASTER_SHAPE.cols - 1));

  const tileRow = Math.floor(latIdx / TILE_SIZE) * TILE_SIZE;
  const tileCol = Math.floor(lonIdx / TILE_SIZE) * TILE_SIZE;

  return {
    tileRow,
    tileCol,
    localRow: latIdx % TILE_SIZE,
    localCol: lonIdx % TILE_SIZE,
  };
}

async function openTile(tileRow: number, tileCol: number): Promise<GeoTIFF> {
  const filename = `lp_${tileRow}_${tileCol}_lerc.tif`;

  const cached = tiffCache.get(filename);
  if (cached) return cached;

  const tiffPromise = fromUrl(`${TILE_BASE_URL}/${filename}`);
  tiffCache.set(filename, tiffPromise);
  return tiffPromise;
}

// --- Public API -----------------------------------------------------------

/**
 * Look up the light-pollution value at a given latitude/longitude.
 *
 * @param lat Latitude in degrees.
 * @param lon Longitude in degrees.
 * @returns Light pollution in cd/m² (matches the Python function's units and
 *          its `0.0` fallback for missing/NaN pixels or a missing tile —
 *          e.g. tiles that were never generated for open ocean).
 */
export async function lightPollution(lat: number, lon: number): Promise<number> {
  const { tileRow, tileCol, localRow, localCol } = resolveTileIndex(lat, lon);

  let tiff: GeoTIFF;
  try {
    tiff = await openTile(tileRow, tileCol);
  } catch {
    // Matches the Python `except FileNotFoundError`-style fallback implied
    // by tiles not existing for e.g. open-ocean regions.
    return 0.0;
  }

  const image = await tiff.getImage();

  // Single-pixel window read — geotiff.js only decodes the internal tile(s)
  // that overlap this window, and (for fromUrl) only fetches those byte
  // ranges over HTTP, matching rasterio's windowed-read efficiency.
  const window: [number, number, number, number] = [
    localCol,
    localRow,
    localCol + 1,
    localRow + 1,
  ];

  const [rasterData] = await image.readRasters({ window });
  const value = (rasterData as unknown as ArrayLike<number>)[0]; // mcd/m^2

  if (value === undefined || Number.isNaN(value)) return 0.0;

  return value * 1e-3; // mcd/m^2 -> cd/m^2, same conversion as the Python
}